// Public proof of possession, never an authentication grant. The nonce and public
// identity are signed; neither a Host header nor caller input chooses the origin.
export const layerManagedHostProof = HttpRouter.add(
  "GET",
  "/.well-known/blackcrab/managed-host-proof",
  Effect.gen(function* () {
    const config = yield* ServerConfig.ServerConfig;
    const request = yield* HttpServerRequest.HttpServerRequest;
    const nonce = new URL(request.url, "http://127.0.0.1").searchParams.get("nonce");
    if (!config.desktopBootstrapSecret || config.host !== "127.0.0.1" ||
        !Number.isInteger(config.port) || config.port < 1 || config.port > 65535) {
      return HttpServerResponse.empty({ status: 404 });
    }
    if (nonce === null || !/^[a-f0-9]{64}$/.test(nonce)) {
      return HttpServerResponse.empty({ status: 400 });
    }
    const descriptor = yield* (yield* ServerEnvironment.ServerEnvironment).getDescriptor;
    const origin = `http://127.0.0.1:${config.port}/`;
    const fields = ["blackcrab-managed-host-proof-v1", nonce, descriptor.environmentId,
      origin, descriptor.serverVersion, descriptor.orchestrationProtocolVersion];
    const proof = createHmac("sha256", config.desktopBootstrapSecret)
      .update(JSON.stringify(fields)).digest("hex");
    return HttpServerResponse.jsonUnsafe({ version: 1, nonce,
      environmentId: descriptor.environmentId, origin,
      serverVersion: descriptor.serverVersion,
      orchestrationProtocolVersion: descriptor.orchestrationProtocolVersion, proof },
      { headers: { "Cache-Control": "no-store" } });
  }),
);

